mapper.sql:
from facility_check_hstry fch inner join facility f on fch.facility_no = f.facility_no inner join partner p on fch.partner_no = p.partner_no inner join mgmt_office mo on mo.apt_cmplex_no = f.apt_cmplex_no left join common_code fac_ty on fac_ty.group_code_no = 'FACILITY_TY' and fac_ty.code_no_cd = f.facility_ty_cd and fac_ty.use_yn = 'Y' left join common_code chk_ty on chk_ty.group_code_no = 'CHECK_TY' and chk_ty.code_no_cd = fch.chk_ty_cd and chk_ty.use_yn = 'Y' left join common_code chk_stts on chk_stts.group_code_no = 'CHECK_STTS' and chk_stts.code_no_cd = fch.chk_stts_cd and chk_stts.use_yn = 'Y' where mo.mgmt_ofc_no = #{searchVO.mgmtOfcNo} and p.apt_cmplex_no = f.apt_cmplex_no
and ( upper(fch.facility_no) like '%' || upper(#{searchWord}) || '%' or upper(f.facility_nm) like '%' || upper(#{searchWord}) || '%' or upper(p.partner_nm) like '%' || upper(#{searchWord}) || '%' )
and fch.chk_ty_cd = #{searchVO.chkTyCd}
and fch.chk_stts_cd = #{searchVO.chkSttsCd}
and fch.chk_dt >= to_date(#{searchVO.chkStartDt}, 'yyyy-mm-dd')
and fch.chk_dt < to_date(#{searchVO.chkEndDt}, 'yyyy-mm-dd') + 1

mapper.insert:

    select 'FCH' || lpad(seq_facility_check_hstry.nextval, 4, '0')
    from dual

insert into facility_check_hstry (
    fac_chk_hstry_no
    , facility_no
    , partner_no
    , chk_dt
    , chk_stts_cd
    , chk_cn
    , rmk
    , reg_dt
    , chk_ty_cd
) values (
    #{facChkHstryNo}
    , #{facilityNo}
    , #{partnerNo}
    , to_date(#{chkDt}, 'yyyy-mm-dd')
    , #{chkSttsCd}
    , #{chkCn}
    , #{rmk}
    , sysdate
    , #{chkTyCd}
)

mapper.update:
update facility_check_hstry
set partner_no = #{partnerNo}
    , chk_dt = to_date(#{chkDt}, 'yyyy-mm-dd')
    , chk_stts_cd = #{chkSttsCd}
    , chk_cn = #{chkCn}
    , rmk = #{rmk}
    , mdf_dt = sysdate
    , chk_ty_cd = #{chkTyCd}
where fac_chk_hstry_no = #{facChkHstryNo}
and facility_no = #{facilityNo}
